_MODULE.globals = {
"rest", "kv", "json", "jwt", "form", "inspect", "colors", "base64", "url", "html", 
"uuid", "ulid", "nanoid", "tools", "copy", "fail", "cli", "input", "expired_token"
}


local heredoc_ids = (table.freeze({MN = true, MIDNIGHT = true}))

_MODULE.ns = vim.api.nvim_create_namespace("midnight.rest")
_MODULE.runs = {}---@type table<integer, integer>

--- the midnight heredocs in a rest buffer: { first = 0-based row of the first
--- line of code, lines = { ... } }
---@param buf integer
function _MODULE.heredocs(buf)
  local __MIDNIGHT_TMP_3__ do local __MIDNIGHT_TMP_4__, __MIDNIGHT_TMP_5__ = pcall(function() return vim.treesitter.get_parser(buf, "hcl") end) if __MIDNIGHT_TMP_4__ then __MIDNIGHT_TMP_3__ = __MIDNIGHT_TMP_5__ else __MIDNIGHT_TMP_3__ = nil end end local parser = __MIDNIGHT_TMP_3__
  if not parser then return {} end
  local tree = parser:parse()[1]
  local query = vim.treesitter.query.parse("hcl", 
  "(heredoc_template (heredoc_identifier) @id) @doc")

  local docs, seen = {}, {}
  for _, captures in query:iter_matches(tree:root(), buf, 0, -1, {all = true}) do
    local doc, id
    for capture, nodes in pairs(captures) do
      do local __MIDNIGHT_TMP_8__ = query.captures[capture]
        if __MIDNIGHT_TMP_8__ == "doc" then doc = nodes[1]
        elseif __MIDNIGHT_TMP_8__ == "id" then id = nodes[#nodes]

        end end
    end

    if doc and id and not seen[doc:id()] and heredoc_ids[vim.treesitter.get_node_text(id, buf):upper()] then
      seen[doc:id()] = true
      local start_row, _, end_row = doc:range()
      docs[#docs + 1] = {
      first = start_row + 1, 
      lines = vim.api.nvim_buf_get_lines(buf, start_row + 1, end_row, false)
      }
    end
  end
  return docs
end

--- is (0-based) row code in a midnight heredoc?
---@param buf integer
---@param row integer
function _MODULE.in_heredoc(buf, row)
  for _, doc in ipairs(_MODULE.heredocs(buf)) do
    if row >= doc.first and row < doc.first + #doc.lines then return true end
  end
  return false
end

--- runs `midnight lint` on each midnight heredoc in a rest buffer
---@param buf? integer
function _MODULE.lint(buf) if buf == nil then buf = vim.api.nvim_get_current_buf() end
  local midnight = require("midnight")
  local args = vim.list_extend({midnight.config.cmd, "lint"}, midnight.factory_args())
  local names = vim.list_extend(vim.deepcopy(_MODULE.globals), midnight.config.globals)
  vim.list_extend(args, {"-g", table.concat(names, ","), "-"})

  local docs = _MODULE.heredocs(buf)

  _MODULE.runs[buf] = (_MODULE.runs[buf] or 0) + 1
  local run = _MODULE.runs[buf]
  local diagnostics, pending = {}, #docs
  if pending == 0 then return vim.diagnostic.reset(_MODULE.ns, buf) end

  for _, doc in ipairs(docs) do
    vim.system(args, {stdin = table.concat(doc.lines, "\n"), text = true}, vim.schedule_wrap(function(res)
      for _, d in ipairs(midnight.parse_lint(res.stdout or "")) do
        d.lnum = d.lnum + doc.first
        diagnostics[#diagnostics + 1] = d
      end
      pending = pending - 1
      if pending == 0 and _MODULE.runs[buf] == run and vim.api.nvim_buf_is_valid(buf) then
        vim.diagnostic.set(_MODULE.ns, buf, diagnostics)
      end
    end))
  end
end

--- is buf part of a rest project (there's a .rest file in it, or a parent dir)?
--- (a bare `.rest`, ex. rest's ~/.rest, doesn't count)
---@param buf integer
function _MODULE.in_project(buf)
  return 
  vim.fs.root(buf, function(name) return name ~= ".rest" and name:match("%.rest$") ~= nil end) ~= nil
end

--- lints rest buffers' heredocs on read, write, and leaving insert mode
function _MODULE.setup()
  local group = vim.api.nvim_create_augroup("midnight.rest", {clear = true})
  vim.api.nvim_create_autocmd({"BufReadPost", "BufWritePost", "InsertLeave"}, {
  group = group, 
  pattern = "*.rest", 
  callback = function(ev) return _MODULE.lint(ev.buf) end
  })
end
return _MODULE
